144	        HttpStatus status = HttpStatus.BAD_REQUEST;
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        return ResponseEntity.status(status).body(detail);
147	    }
