180	        logger.debug("Invalid address at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
181	        HttpStatus status = HttpStatus.BAD_REQUEST;
182	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
183	        return ResponseEntity.status(status).body(detail);
184	    }
