186	    /**
187	     * Handles {@link DisposableEmailException} thrown when a supplied email address belongs to a
188	     * disposable-email domain on the blocklist, returning a 400 Bad Request so a disposable email
189	     * is rejected rather than surfacing as an unexpected 500.
190	     *
191	     * @param e The {@link DisposableEmailException} to be handled
192	     * @param request {@link HttpServletRequest} object referring to the current request.
193	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
194	     */
195	    @ExceptionHandler(DisposableEmailException.class)
196	    @ResponseBody
