198	        logger.debug("Disposable email at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
199	        HttpStatus status = HttpStatus.BAD_REQUEST;
200	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
201	        return ResponseEntity.status(status).body(detail);
202	    }
