204	    /**
205	     * Handles {@link InvalidRegistrationDateException} thrown when a supplied registration date is
206	     * later than the server's current date, returning a 400 Bad Request so a future-dated
207	     * registration is rejected rather than surfacing as an unexpected 500.
208	     *
209	     * @param e The {@link InvalidRegistrationDateException} to be handled
210	     * @param request {@link HttpServletRequest} object referring to the current request.
211	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
212	     */
213	    @ExceptionHandler(InvalidRegistrationDateException.class)
214	    @ResponseBody
215	    public ResponseEntity<ProblemDetail> handleInvalidRegistrationDateException(InvalidRegistrationDateException e, HttpServletRequest request) {
216	        logger.debug("Invalid registration date at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
217	        HttpStatus status = HttpStatus.BAD_REQUEST;
218	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
219	        return ResponseEntity.status(status).body(detail);
220	    }
221	
222	    /**
223	     * Handles exception thrown by Bean Validation on controller methods parameters
224	     *
225	     * @param e The {@link MethodArgumentNotValidException} to be handled
226	     * @param request {@link HttpServletRequest} object referring to the current request.
227	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
228	     */
229	    @ExceptionHandler(MethodArgumentNotValidException.class)
230	    @ResponseBody
231	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
232	        HttpStatus status = HttpStatus.BAD_REQUEST;
233	        BindingErrorsResponse errors = new BindingErrorsResponse();
234	        BindingResult bindingResult = e.getBindingResult();
235	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
236	        if (bindingResult.hasErrors()) {
237	            errors.addAllErrors(bindingResult);
238	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
239	                .map(FieldError::getField)
240	                .distinct()
241	                .toList();
242	            detail.setProperty("errors", invalidFields);
243	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
244	                .map(fieldError -> {
245	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
246	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
247	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
248	                        fieldError.getField(),
249	                        defaultMessage,
250	                        rejectedValue);
251	                    return new ValidationMessageDto(message)
252	                        .putAdditionalProperty("field", fieldError.getField())
253	                        .putAdditionalProperty("rejectedValue", rejectedValue)
254	                        .putAdditionalProperty("defaultMessage", defaultMessage);
255	                })
256	                .toList();
257	            logger.debug("Validation error at {} {}: {}",
258	                request.getMethod(),
259	                request.getRequestURI(),
260	                bindingResult.getFieldErrors());
261	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
262	            return ResponseEntity.status(status).body(detail);
263	        }
264	        return ResponseEntity.status(status).body(detail);
265	    }
