55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
77	
78	    private final OwnerAuditEventPublisher auditEventPublisher;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper,
84	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
85	                                 OwnerAuditEventPublisher auditEventPublisher) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
91	        this.auditEventPublisher = auditEventPublisher;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
112	        Owner owner = this.clinicService.findOwnerById(ownerId);
113	        if (owner == null) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
117	    }
118	
119	    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning},
120	     *  {@code capacityWarning} and {@code riskFlag} flags the same way for every owner response. */
121	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
122	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
123	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
124	        ownerDto.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
125	        ownerDto.setRiskFlag(isRiskFlag(owner));
126	        return ownerDto;
127	    }
128	
129	    /** Compute the read-only {@code riskFlag}: true when the owner is a possible duplicate, its
130	     *  email domain is disposable-adjacent, or its city is over its soft capacity. */
131	    private boolean isRiskFlag(Owner owner) {
132	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
133	            || DisposableEmailValidator.isDisposableAdjacent(owner.getEmail())
134	            || this.clinicService.isCityOverSoftCapacity(owner.getCity());
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
140	        // A create retried with an already-seen idempotency key returns the originally created
141	        // owner with 200, rather than creating a duplicate.
142	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
143	        if (existingId != null) {
144	            Owner existing = this.clinicService.findOwnerById(existingId);
145	            if (existing != null) {
146	                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
147	            }
148	        }
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        AddressValidator.validate(owner.getAddress());
152	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
153	        DisposableEmailValidator.validate(owner.getEmail());
154	        RegistrationDateValidator.validate(owner.getRegistrationDate());
155	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
156	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
157	        }
158	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
159	        // and postcode are automatically the same household. It no longer gates duplicate detection
160	        // (that is the identity key alone) but still drives household-derived fields.
161	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
162	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
163	        // Duplicate detection is the single identity key: reject only when the new owner's whole
164	        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
165	        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
166	        // telephones have distinct keys and are created as a soft match rather than rejected.
167	        if (this.clinicService.isIdentityKeyInUse(owner)) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
171	            return new ResponseEntity<>(HttpStatus.CONFLICT);
172	        }
173	        this.clinicService.saveOwner(owner, sharesHousehold);
174	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
175	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
176	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
177	            ownerMapper.formatMembershipLevel(owner));
178	        this.auditEventPublisher.ownerCreated(owner, ownerMapper.formatMembershipLevel(owner));
179	        // Enqueue a welcome notification for the newly created owner.
180	        NOTIFY.info("welcome notification: owner id={} memberId={}", owner.getId(), owner.getMemberId());
181	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
195	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
196	        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
197	        AddressValidator.validate(currentOwner.getAddress());
198	        currentOwner.setCity(ownerFieldsDto.getCity());
199	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
200	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
201	        currentOwner.setLastName(ownerFieldsDto.getLastName());
202	        currentOwner.setTitle(ownerMapper.mapTitle(ownerFieldsDto.getTitle()));
203	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
204	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
205	        this.clinicService.saveOwner(currentOwner);
206	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Transactional
211	    @Override
212	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        this.clinicService.deleteOwner(owner);
218	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
229	        Pet pet = petMapper.toPet(petFieldsDto);
230	        owner.setId(ownerId);
231	        pet.setOwner(owner);
232	        pet.getType().setName(null);
233	        this.clinicService.savePet(pet);
234	        PetDto petDto = petMapper.toPetDto(pet);
235	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
236	            .buildAndExpand(pet.getId()).toUri());
237	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
243	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
244	        if (currentOwner != null) {
245	            Pet currentPet = this.clinicService.findPetById(petId);
246	            if (currentPet != null) {
247	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
248	                currentPet.setName(petFieldsDto.getName());
249	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
250	                this.clinicService.savePet(currentPet);
251	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
260	        HttpHeaders headers = new HttpHeaders();
261	        Visit visit = visitMapper.toVisit(visitFieldsDto);
262	        Pet pet = new Pet();
263	        pet.setId(petId);
264	        visit.setPet(pet);
265	        this.clinicService.saveVisit(visit);
266	        VisitDto visitDto = visitMapper.toVisitDto(visit);
267	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
268	            .buildAndExpand(visit.getId()).toUri());
269	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
270	    }
271	
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
276	        Owner owner = this.clinicService.findOwnerById(ownerId);
277	        if (owner != null) {
278	            Pet pet = owner.getPet(petId);
279	            if (pet != null) {
280	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
281	            }
282	        }
283	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	    }
285	}
